@startuml

class Center {
  + name : string
  + address : string
}

class Room {
  + number : int
  + maximumCapacity : int
}

class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

class Trainer extends Person {
  + diploma : string
}

class Session {
  + date : date
  + startingHour : time
}

class GroupSession extends Session {
  + type : string
}

class IndividualSession extends Session {
}

class Participation {
}

class Supervision {
}

Center "1" *-- "1..*" Room
Center "1" -- "*" Session
Room "1" -- "*" Session
Person "0..*" -- "*" Participation : participates in
Session "1" -- "0..1" Participation : is attended by
Trainer "1" -- "*" Supervision : supervises
Session "1" -- "0..1" Supervision : is supervised by
GroupSession "1" -- "1" Supervision : requires

@enduml

